/* Deterministic WbW effects. t is source milliseconds, never wall-clock time. */
window.FrameEffects=(()=>{
const names={bounce_beat:'Bounce Beat',shake_it:'Shake It',zoom_punch:'Zoom Punch',fade_glow:'Fade Glow',gradient_flow:'Gradient Flow',duotone_pulse:'Duotone Pulse',karaoke_bar:'Karaoke Bar',split_focus:'Split Focus',handwritten:'Handwritten',big_word_focus:'Big Word Focus'};
const palettes={aurora:['#ac83ff','#6cf5dc'],sunset:['#ff8066','#ffdf80','#fc72c7'],ocean:['#49baff','#87fff2'],neon:['#fd67f9','#9e89ff','#58f5ff'],fire:['#ff5858','#ffad42','#fff2a8'],ice:['#ffffff','#b4ddff']};
function palette(draft,x,w,fallback){if(draft.text_mode==='solid')return draft.text_color||'#ffffff';if(draft.text_mode==='gradient'){const stops=palettes[draft.text_gradient]||palettes.aurora,p=clamp(x/w)*(stops.length-1),i=Math.min(stops.length-2,Math.floor(p));return mix(stops[i],stops[i+1],p-i)}return fallback}
const defaults={intensity:.7,duration_ms:350,decay_ms:300,color_a:'#ac83ff',color_b:'#6cf5dc',zoom:2.2,blur:true,glitch:false,whole_line:false,shimmer:false,bar:false,focus_multiplier:2.5,ghost:false,split:.55,horizontal:false};
const clamp=x=>Math.max(0,Math.min(1,x)),back=t=>1+2.70158*(t-1)**3+1.70158*(t-1)**2;
function bounce(t){if(t<1/2.75)return 7.5625*t*t;if(t<2/2.75){t-=1.5/2.75;return 7.5625*t*t+.75}if(t<2.5/2.75){t-=2.25/2.75;return 7.5625*t*t+.9375}t-=2.625/2.75;return 7.5625*t*t+.984375}
function state(effect,elapsed,duration,o){let p=clamp(elapsed/o.duration_ms),s={opacity:elapsed>=0?1:0,scale:1,x:0,y:0,rotation:0,blur:0,glow:0};if(effect==='bounce_beat'){p=clamp((elapsed+50)/o.duration_ms);Object.assign(s,{opacity:Math.min(1,p*4),scale:Math.max(.01,p+o.intensity*(back(p)-p)),y:-20*o.intensity*(1-bounce(p))})}if(effect==='zoom_punch'){const e=p>=1?1:1-2**(-10*p);Object.assign(s,{opacity:Math.min(1,p*3),scale:1+(o.zoom-1)*(1-e),blur:o.blur?8*(1-e):0})}if(effect==='shake_it'&&elapsed>=0&&elapsed<duration+150){const a=8*o.intensity*Math.exp(-elapsed/o.duration_ms),t=elapsed/1000;Object.assign(s,{x:a*Math.sin(t*40),y:a*.4*Math.sin(t*55+.7),rotation:a*.05*Math.sin(t*30)})}if(effect==='fade_glow')Object.assign(s,{opacity:clamp(elapsed/o.duration_ms)*(1-clamp((elapsed-duration)/Math.max(1,o.decay_ms))),glow:elapsed>=0?(6+18*Math.sin(Math.PI*clamp(elapsed/duration)))*o.intensity:0});if(effect==='handwritten')Object.assign(s,{opacity:p,y:8*(1-p)});return s}
function mix(a,b,t){const rgb=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)),x=rgb(a),y=rgb(b);return `rgb(${x.map((v,i)=>Math.round(v+(y[i]-v)*clamp(t))).join(',')})`}
function media(ctx,m,w,h,draft){const o={...defaults,...draft.effect_options},rw=o.horizontal?w*o.split:w,rh=o.horizontal?h:h*o.split,mw=m.videoWidth||m.naturalWidth,mh=m.videoHeight||m.naturalHeight,s=Math.min(rw/mw,rh/mh)*draft.video_zoom;ctx.save();ctx.beginPath();ctx.rect(0,0,rw,rh);ctx.clip();ctx.drawImage(m,(rw-mw*s)/2,(rh-mh*s)/2,mw*s,mh*s);ctx.restore()}
function draw(ctx,w,h,cue,words,t,draft){const effect=draft.style,o={...defaults,...draft.effect_options},unit=w/480,size=Math.max(12,Math.round(w*.082))*draft.text_scale;ctx.save();ctx.font=`700 ${size}px ${effect==='handwritten'?'"Segoe Print", cursive':'Inter'}`;ctx.textAlign='left';ctx.textBaseline='top';const gap=ctx.measureText(' ').width,limit=w*.86*(effect==='split_focus'&&o.horizontal?1-o.split:1);let rows=[],row=[],length=0;words.forEach((word,n)=>{const text=effect==='handwritten'?word.text:word.text.toUpperCase(),width=ctx.measureText(text).width;if(row.length&&length+gap+width>limit){rows.push({row,length});row=[];length=0}if(row.length)length+=gap;row.push({word,n,text,x:length,width});length+=width});if(row.length)rows.push({row,length});let cx=w/2,cy=h*draft.text_y;if(effect==='split_focus'){if(o.horizontal)cx=w*(1+o.split)/2;else cy=h*(o.split+(1-o.split)*draft.text_y)}
if(effect==='duotone_pulse'){const beats=[...new Set(draft.captions.flatMap(c=>c.words.map(a=>a.start_ms)).filter(a=>a<=t))].sort((a,b)=>a-b);if(beats.length){ctx.globalAlpha=(180/255)*o.intensity*(1-clamp((t-beats.at(-1))/o.duration_ms))**2;ctx.fillStyle=(beats.length-1)%2?o.color_b:o.color_a;ctx.fillRect(0,0,w,h);ctx.globalAlpha=1}}
let focus=words.findIndex(a=>a.is_focus);if(focus<0){const stop=new Set('a an the i you me my to of and o os as eu de do da e em um uma'.split(' '));let eligible=words.map((a,n)=>n).filter(n=>!stop.has(words[n].text.toLowerCase().replace(/[.,!?]/g,'')));if(!eligible.length)eligible=words.map((a,n)=>n);focus=eligible.reduce((best,n)=>best<0||words[n].end_ms-words[n].start_ms>words[best].end_ms-words[best].start_ms?n:best,-1)}
rows.forEach(({row,length},r)=>row.forEach(({word,n,text,x:offset,width})=>{let x=cx-length/2+offset,y=cy-rows.length*size*1.22/2+r*size*1.22,elapsed=t-word.start_ms,duration=word.end_ms-word.start_ms,s=state(effect,elapsed,duration,o),color=o.color_a;if(['gradient_flow','karaoke_bar','duotone_pulse','split_focus'].includes(effect))s.opacity=1;if(effect==='gradient_flow'){let p=clamp((t-cue.speech_start_ms)/(cue.speech_end_ms-cue.speech_start_ms));color=mix(o.color_a,o.color_b,o.shimmer?(p+x/w*1500/o.duration_ms)%1:p)}if(effect==='shake_it'&&o.whole_line){const current=words.find(a=>t>=a.start_ms&&t<a.end_ms);if(current)s=state(effect,t-current.start_ms,current.end_ms-current.start_ms,o)}if(effect==='big_word_focus'){if(n!==focus){if(!o.ghost)return;s.opacity=.16}else{s=state('bounce_beat',elapsed,duration,o);s.scale*=o.focus_multiplier;x=(w-width)/2}}color=palette(draft,x+width/2,w,color);if(s.opacity<=0)return;ctx.save();ctx.globalAlpha=s.opacity;ctx.translate(x+width/2+s.x*unit,y+size/2+s.y*unit);ctx.scale(s.scale,s.scale);ctx.rotate(s.rotation*Math.PI/180);ctx.filter=s.blur?`blur(${s.blur*unit}px)`:'none';ctx.shadowColor=color;ctx.shadowBlur=s.glow*unit;ctx.fillStyle=color;const left=-width/2,top=-size/2;if(effect==='karaoke_bar'){ctx.fillStyle=o.color_b;ctx.fillText(text,left,top);ctx.fillStyle=color;const progress=clamp(elapsed/duration);if(o.bar)ctx.fillRect(left,top+size+4*unit,width*progress,3*unit);else{ctx.beginPath();ctx.rect(left-1,top-5,width*progress+1,size*2);ctx.clip();ctx.fillText(text,left,top)}}else{if(effect==='shake_it'&&o.glitch&&elapsed>=0&&elapsed<duration&&Math.floor(elapsed/80)%3===0){ctx.fillStyle='#ff465a';ctx.fillText(text,left-3*unit,top);ctx.fillStyle='#4696ff';ctx.fillText(text,left+3*unit,top);ctx.fillStyle=color}ctx.fillText(text,left,top)}ctx.restore()}));ctx.restore()}
return {names,defaults,draw,media,state,palettes,palette};})();
